  ('pmk-113-2012-page-5-pasal-11', 'pmk-113-2012', '11', NULL, 5, 46, 'Pasal 11'),
  ('pmk-113-2012-page-5-pasal-11-ayat-1', 'pmk-113-2012', '11 ayat (1)', NULL, 5, 47, '(1) Perjalanan Dinas Jabatan untuk mengikuti rapat, seminar, dan sejenisnya sebagaimana dimaksud dalam Pasal 5 huruf
b dilaksanakan dengan biaya Perjalanan Dinas Jabatan yang ditanggung oleh panitia penyelenggara.'),
  ('pmk-113-2012-page-5-pasal-11-ayat-2', 'pmk-113-2012', '11 ayat (2)', NULL, 5, 48, '(2) Dalam hal biaya Perjalanan Dinas Jabatan untuk mengikuti rapat, seminar, dan sejenisnya sebagaimana dimaksud
