INSERT INTO `knowledge_chunk` (`id`, `document_id`, `article`, `section`, `page`, `sequence`, `text`) VALUES
  ('pmk-113-2012-page-8-pasal-32', 'pmk-113-2012', '32', NULL, 8, 100, 'Pasal 32
Tata cara pengajuan tagihan kepada PPK, pengujian surat permintaan pembayaran, dan penerbitan Surat Perintah
Membayar oleh Pejabat Penanda Tangan SPM, dan penerbitan Surat Perintah Pencairan Dana (SP2D) oleh Kantor Pelayanan
Perbendaharaan Negara (KPPN) berpedoman pada Peraturan Menteri Keuangan mengenai tata cara pembayaran atas beban
Anggaran Pendapatan dan Belanja Negara.'),
  ('pmk-113-2012-page-8-pasal-33', 'pmk-113-2012', '33', NULL, 8, 101, 'Pasal 33'),
  ('pmk-113-2012-page-8-pasal-33-ayat-1', 'pmk-113-2012', '33 ayat (1)', NULL, 8, 102, '(1) Dalam hal terjadi pembatalan pelaksanaan Perjalanan Dinas Jabatan, biaya pembatalan dapat dibebankan pada DIPA
satuan kerja berkenaan.'),
  ('pmk-113-2012-page-8-pasal-33-ayat-2', 'pmk-113-2012', '33 ayat (2)', NULL, 8, 103, '(2) Dokumen yang harus dilampirkan dalam rangka pembebanan biaya pembatalan sebagaimana dimaksud pada ayat (1)
meliputi:
a. Surat Pernyataan Pembatalan Tugas Perjalanan Dinas Jabatan dari atasan Pelaksana SPD, atau paling rendah
Pejabat Eselon II bagi Pelaksana SPD di bawah Pejabat Eselon III ke bawah, yang dibuat sesuai format sebagaimana
tercantum dalam Lampiran VII yang merupakan bagian tidak terpisahkan dari Peraturan Menteri ini;
b. Surat Pernyataan Pembebanan Biaya Pembatalan Perjalanan Dinas Jabatan yang dibuat sesuai format
sebagaimana tercantum dalam Lampiran VIII yang merupakan bagian tidak terpisahkan dari Peraturan Menteri ini;
c. Pernyataan/Tanda Bukti Besaran Pengembalian Biaya Transpor dan/atau biaya penginapan dari perusahaan jasa
transportasi dan/atau penginapan yang disahkan oleh PPK.'),
  ('pmk-113-2012-page-8-pasal-33-ayat-3', 'pmk-113-2012', '33 ayat (3)', NULL, 8, 104, '(3) Biaya pembatalan yang dapat dibebankan pada DIPA satuan kerja sebagaimana dimaksud pada ayat (1) sebagai berikut:
a. biaya pembatalan tiket transportasi atau biaya penginapan; atau
b. sebagian atau seluruh biaya tiket transportasi atau biaya penginapan yang tidak dapat dikembalikan/refund.
BAB IX
PERTANGGUNGJAWABAN BIAYA PERJALANAN DINAS'),
